import { expect, test, uniqueName } from "../../fixtures";

test.describe("vendor list", () => {
  test("list vendors with search, status filter, and pagination", { tag: "@VEN-05" }, async ({ apiAs }) => {
    const member = await apiAs("member");
    const token = uniqueName("Freight Batch");

    for (let i = 0; i < 25; i++) {
      const res = await member.post("/api/vendors", {
        data: { name: `${token} ${String(i).padStart(2, "0")}`, category: "logistics", contact_email: `ops${i}.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com` },
      });
      expect(res.status(), await res.text()).toBe(201);
    }

    // Status filter: vendors in this batch are all draft, so approved filter should return only approved items.
    const approved = await member.get("/api/vendors", { params: { status: "approved", limit: 100 } });
    expect(approved.status(), await approved.text()).toBe(200);
    const approvedPage = await approved.json();
    for (const v of approvedPage.items) {
      expect(v.status, JSON.stringify(v)).toBe("approved");
    }
    expect(approvedPage.total).toBe(approvedPage.items.length);

    // Pagination: scope to our batch so the total is exactly 25.
    const page = await member.get("/api/vendors", { params: { q: token, limit: 10, offset: 20 } });
    expect(page.status(), await page.text()).toBe(200);
    const pageBody = await page.json();
    expect(pageBody.items).toHaveLength(5);
    expect(pageBody.total).toBe(25);

    // Search: every returned name contains the term, ignoring case.
    const search = await member.get("/api/vendors", { params: { q: "freight", limit: 100 } });
    expect(search.status(), await search.text()).toBe(200);
    const searchBody = await search.json();
    expect(searchBody.items.length).toBeGreaterThan(0);
    for (const v of searchBody.items) {
      expect(v.name.toLowerCase(), JSON.stringify(v)).toContain("freight");
    }
  });
});
